package com.distributedexam.client.ui;
import com.distributedexam.client.RMIClientConnector;import com.distributedexam.common.*;import javax.swing.*;import java.awt.*;
public class CoordinatorDashboard extends JFrame {private final RMIClientConnector c;private final JTextArea body=new JTextArea(24,85);public CoordinatorDashboard(RMIClientConnector c,User u){super("Coordinator Dashboard - "+u.getUsername());this.c=c;body.setEditable(false);add(new JScrollPane(body));JButton refresh=new JButton("Refresh");refresh.addActionListener(e->load());add(refresh,BorderLayout.SOUTH);pack();setDefaultCloseOperation(EXIT_ON_CLOSE);setLocationRelativeTo(null);load();}private void load(){try{DashboardSnapshot d=c.getDashboardService().getCoordinatorSnapshot();StringBuilder b=new StringBuilder("Rooms: ").append(d.totalRooms).append(" | online: ").append(d.onlineRooms).append(" | offline: ").append(d.offlineRooms).append("\nRunning exams: ").append(d.runningExams).append(" | attendance records: ").append(d.attendanceCount).append(" | submissions: ").append(d.submissionCount).append(" | open incidents: ").append(d.openIncidents).append("\n\nRoom status: ").append(d.roomStatusSummary).append("\nAttendance % by room: ").append(d.attendancePercentByRoom).append("\nSubmission progress %: ").append(d.submissionProgressByRoom).append("\nIncident summary: ").append(d.incidentSummary).append("\nExam completion: ").append(d.examCompletionStatus).append("\n\nRecent events:\n");for(ExamEvent e:d.recentEvents)b.append(e.getEventTimestamp()).append(" | room ").append(e.getRoomId()).append(" | ").append(e.getEventType()).append(" | ").append(e.getDescription()).append('\n');body.setText(b.toString());}catch(Exception e){body.setText("Unable to load server data: "+e.getMessage());}}}
